import os, time, requests

TI = "https://ti.example.com/api/v1"
TOKEN = os.environ["TI_API_TOKEN"]          # injected by the vault, never hard-coded
_cache = {}                                 # {key: (expires_at, value)}

def lookup_ip(ip, ttl=900):
    hit = _cache.get(ip)
    if hit and hit[0] > time.time():
        return hit[1]                       # cache hit: no API call
    try:
        r = requests.get(f"{TI}/ip/{ip}", timeout=3,
                         headers={"Authorization": f"Bearer {TOKEN}"})
        r.raise_for_status()
        value = r.json()
    except requests.RequestException as e:
        return {"status": "source unavailable", "error": type(e).__name__}
    _cache[ip] = (time.time() + ttl, value)
    return value

def score(ti, host):
    points = 0
    points += 50 if ti.get("verdict") == "malicious" else 0
    points += 30 if host.get("criticality") == "high" else 0
    points += 20 if host.get("user_is_admin") else 0
    return min(points, 100)

